      txt(c, 'LIFE SUPPORT RESERVE', 14, 136, { size: 10, col: COL.peri }); bar(c, 14, 142, W - 28, 8, clamp(1 - (m.base + Math.max(0, m.S - a.ok)) / 50), { col: COL.lav });
