const WHERE = ['Deck 4 scrubber', 'Sickbay vent', 'Mess hall lights', 'Plasma relay 7', 'Lift B door', 'Cabin heater', 'Hydroponics pump', 'Shuttle bay seal', 'Replicator 2', 'Plant CO2 sensor', 'Cargo plating', 'Bridge EPS tap'];
