      txt(c, `Field strength ${Fv} MC  (limit ${limF})`, 14, 100, { size: 12, col: m.soaked && x.Fs > limF ? P.bad : COL.ink }); bar(c, 14, 106, W - 28, 10, Fv / (limF * 1.1), { mark: 1 / 1.1, col: COL.peri });
