    m.hint = () => { if (m.done) return [['Enter', true]]; const l = Lf(); return showing(l) && m.lt >= l.on + 0.25 ? [['Arrow' + { L: 'Left', R: 'Right', D: 'Down' }[l.e], true]] : []; };
