      m.plan.forEach((p, j) => txt(c, `${j + 1}. ${p.n} — ${p.min} min`, 10, 34 + j * 15, { size: 10, col: j ? COL.dim : COL.ink }));
      txt(c, m.sw < 0 ? 'switch: GREEN (Space to announce)' : `switch: YELLOW · ${el().toFixed(1)} s`, 10, 92, { size: 10, col: m.sw < 0 ? COL.dim : COL.warn });
