      if (a === 'L' || a === 'R') { m.s = Math.max(1, Math.min(10, m.s + (a === 'R' ? 1 : -1))); return true; }
      if (SPACE(code)) { if (!ok()) { m.fault('approved red'); return true; } m.round++; m.li++; if (m.li >= 3) m.win(); else m.s = L().s0; return true; }
      return !!a;
