          txt(c, k, x + 4, y + 11, { size: 8, col: COL.dim }); txt(c, m.val[j] < 0 ? '?' : L[j][m.val[j]], x + 4, y + 26, { size: 9, col: m.val[j] < 0 ? COL.warn : COL.ink });
