        txt(c, `${w.d}: ${w.n}`, 12, y + 13, { size: 9 }); txt(c, `${w.v} ${w.u}`, 196, y + 13, { size: 10 }); txt(c, `${w.lo}–${w.hi}`, 250, y + 13, { size: 9, col: COL.dim });
