      if (bad.has(i)) { fault = ['tone', 'silent', 'light'][ri(r, 0, 2)]; if (fault === 'tone') { const j = ri(r, 0, 5); play[j] = (play[j] + ri(r, 1, 3)) % 4; } if (fault === 'silent') play = null; if (fault === 'light') light = false; }
