    seals.forEach((s, i) => { let shown = s; if (i % 2 === 1 || r() < 0.25) { const p = ri(r, 0, 3); shown = s.slice(0, p) + ((+s[p] + ri(r, 1, 8)) % 10) + s.slice(p + 1); } lines.push({ s: `SEAL ${shown}`, tick: shown === s }); });
