      txt(c, `${SH[q.sh]} shift · ${q.dept}`, 26, 70, { size: 11, col: COL.dim }); txt(c, `${q.bad ? '▼' : '▲'} ${q.obs}`, 26, 92, { size: 12, col: q.bad ? COL.warn : P.good });
