    m.drift = pick(r, [-1, 1]) * rf(r, 0.12, 0.2) * k; m.gusts = Array.from({ length: 12 }, (_, j) => [j * 1.7 + rf(r, 0.5, 1.4), pick(r, [-1, 1]) * rf(r, 0.06, 0.12) * k]);
