    m.leg = 0; m.p = 0; m.wait = false; m.jolted = false; m.flash = 0; m.msg = ''; m.round = 1; m.rounds = n;
    const L = () => m.legs[m.leg], inZone = () => m.p >= L().len - ZONE;
