      if ((a === 'L' || a === 'R') && m.wait) { if (a !== L().turn) { m.fault('wrong turn'); m.flash = 0.7; m.msg = 'WRONG WAY'; return true; } m.wait = false; m.leg++; m.p = 0; m.jolted = false; m.round = m.leg + 1; }
