      if (a === 'L') m.cur = Math.max(0, m.cur - 1); else if (a === 'R') m.cur = Math.min(2, m.cur + 1);
      else if (a === 'U') m.w[m.cur] = (m.w[m.cur] + 1) % 10; else if (a === 'D') m.w[m.cur] = (m.w[m.cur] + 9) % 10;
