      if (m.k > 0 && m.k <= n) { const h = m.legs[m.k - 1]; if (h) { c.fillStyle = COL.warn; c.fillRect(sx + (m.k - 0.5) * dx - 4, y + (h === 'above' ? -16 : 8), 8, 8); } }
