        txt(c, `${f.done ? '✓' : f.pend >= 0 ? '…' : '⚑'} ${f.who}  ${f.post} ${f.shift} h  (${f.hrs} h on)`, 12, y + 14, { size: 10, col: f.done ? P_.good : COL.ink });
