    m.lines = shuffle(r, DEPTS).slice(0, 4).map(([dept, target]) => { const a = ri(r, 36, 100) * 10, b = a + pick(r, [40, 60, 80, 90, 110, 130]); return { dept, target, code: hhmm(a) + hhmm(b) }; });
