        box(c, x, 8, 90, 124, 'rgba(255,255,255,.05)', on ? COL.gold : gap ? P.bad : COL.dim, 6); txt(c, `${WATCH[i]} ${w.crew.length}`, x + 6, 22, { size: 11, col: COL.gold });
