// ---- yeoman__update-log-and-duty-roster.js
const m699 = (() => {
// Yeoman: update the log and the duty roster. Six names, three watches of two. Every name carries the time they last came off duty; a watch
// may only take someone who has had the full rest gap since then, and nobody stands two watches. Move the cursor over the roster grid and
// write a name into each slot: the grid shows each name's rest gap against the watch under the cursor.
const { define, machine, DIG, ARROW, pick, shuffle, txt, box, COL } = __kit;
const NAMES = ['Abara', 'Brandt', 'Chen', 'Dasari', 'Eklund', 'Fonseca', 'Gale', 'Huang', 'Ivers', 'Juarez'];
const WATCH = [['Alpha', 0], ['Beta', 6], ['Gamma', 12]], REST = 10;
const clock = (h) => String(((h % 24) + 24) % 24).padStart(2, '0') + '00';

return define({
  job: { billet: 'yeoman', label: 'Update log and duty roster', type: 'loop' },
  title: 'Watch bill with rest gaps', dept: 'command', host: 'console', tool: 'Watch roster grid',
  how: 'Move to a roster slot (arrows) and write a name into it (1-6). Each name shows its rest since last duty against that watch: it needs 10 hours, and nobody may stand two watches.',
  keys: ['arrows pick a slot', '1-6 write a name'], limit: 32, maxFaults: 3,
  fingerprint: { verb: 'ink watch bill', input: 'digits+arrows', win: 'all six watch slots inked with distinct crew who each had the full rest since their last duty',
    fail: 'writing a name onto a watch inside their rest gap, or onto a second watch',
    rule: 'Arrows move the cursor across the Alpha, Beta and Gamma slots. The name list shows each person\'s rest gap to the watch under the cursor; press their number only if it reads 10 h or more and they are not already on the bill.' },
  rush: 'Copied yesterday\'s roster forward and initialled it.',
  captions: { 'short rest': 'roster clerk tuts', 'two watches': 'double-booking chime' },
  create(seed, opts) {
    const m = machine(this, seed, opts), r = m.rnd, names = shuffle(r, NAMES).slice(0, 6);
    const off = [-10, -10, pick(r, [-8, -6, -4]), pick(r, [-8, -6, -4]), pick(r, [-8, -6, -4, -2]), pick(r, [-8, -6, -4, -2])];
    const order = shuffle(r, [0, 1, 2, 3, 4, 5]); m.crew = order.map(i => ({ name: names[i], off: off[i], sol: i }));   // sol: the slot index 0..5 that works
    m.slots = Array(6).fill(-1); m.cx = 0; m.cy = 2; m.rounds = 6; m.round = 0;
    const gap = (p, w) => WATCH[w][1] - p.off;
    m.key = (code, down = true) => {
      if (m.state !== 'play') return false; const a = ARROW(code), d = DIG(code);
      if (a) { if (down) { if (a === 'U') m.cy = (m.cy + 2) % 3; if (a === 'D') m.cy = (m.cy + 1) % 3; if (a === 'L' || a === 'R') m.cx = 1 - m.cx; } return true; }
      if (d < 1 || d > 6) return false; if (!down) return true; const p = m.crew[d - 1], s = m.cy * 2 + m.cx;
      if (m.slots.includes(d - 1) && m.slots[s] !== d - 1) { m.fault('two watches'); return true; }
      if (gap(p, m.cy) < REST) { m.fault('short rest'); return true; }
      m.slots[s] = d - 1; m.round = m.slots.filter(x => x >= 0).length; m.ev('ink', { s, p: d - 1 });
      if (m.slots.every(x => x >= 0)) m.win(); return true;
    };
    m.tick = (dt) => { m.live(dt); };
    m.hint = () => {
      const s = m.cy * 2 + m.cx; if (m.slots[s] < 0) return [[`Digit${m.crew.findIndex(p => p.sol === s) + 1}`, true]];
      const todo = m.slots.findIndex(x => x < 0); if (todo < 0) return []; return [[Math.floor(todo / 2) !== m.cy ? 'ArrowDown' : 'ArrowRight', true]];
    };
    m.bad = () => { const i = m.crew.findIndex(p => gap(p, m.cy) < REST); return i < 0 ? 'ArrowUp' : `Digit${i + 1}`; };
    m.view = () => ({ crew: m.crew.map(p => [p.name, p.off]) });
    m.buttons = () => [['ArrowUp', '▲'], ['ArrowDown', '▼'], ['ArrowLeft', '◀▶'], ...m.crew.map((p, i) => [`Digit${i + 1}`, `${i + 1}`])];
    m.draw = (c, W, H, P) => {
      txt(c, 'WATCH BILL', 10, 16, { size: 10, col: COL.peri });
      WATCH.forEach(([w, h], y) => { txt(c, `${w} ${clock(h)}`, 10, 42 + y * 34, { size: 11, col: COL.gold });
        for (let x = 0; x < 2; x++) { const s = y * 2 + x, on = y === m.cy && x === m.cx, p = m.slots[s]; box(c, 92 + x * 74, 28 + y * 34, 68, 24, on ? 'rgba(244,194,91,.2)' : 'rgba(255,255,255,.05)', on ? COL.gold : COL.dim, 4);
          txt(c, p >= 0 ? m.crew[p].name : '—', 126 + x * 74, 44 + y * 34, { size: 10, align: 'center', col: p >= 0 ? COL.ink : COL.dim }); } });
      txt(c, `REST TO ${WATCH[m.cy][0].toUpperCase()} (need ${REST} h)`, 252, 16, { size: 10, col: COL.peri });
      m.crew.forEach((p, i) => { const g = gap(p, m.cy), used = m.slots.includes(i), ok = g >= REST; const y = 32 + i * 21;
        txt(c, `${i + 1} ${p.name}`, 252, y, { size: 11, col: used ? COL.dim : COL.ink }); txt(c, `off ${clock(p.off)}`, 252, y + 9, { size: 8, col: COL.dim });
        txt(c, used ? 'on bill' : `${ok ? '✓' : '✗'} ${g} h`, 392, y, { size: 11, align: 'right', col: used ? COL.dim : ok ? P.good : P.bad }); });
      txt(c, `${m.slots.filter(x => x >= 0).length} / 6 inked`, 10, H - 10, { size: 11, col: COL.pale });
    };
    return m;
  },
});
})();
// ---- yeoman__walk-the-captains-deck-round-notes__quiet_watch.js
const m700 = (() => {
// Yeoman: walk the captain's deck round notes. At each station read the captain's note to the officer on duty. The officer talks: a nod, a
// "will do", an answer about something else, and somewhere in there the real answer to this note. Tap E on the real answer (specific, and
// about this note) to write it beside the note. Taking a nod or an off-topic answer lets the small complaint grow into a crisis.
const { define, machine, room, rf, shuffle, clamp } = __kit;
const NOTES = [
  ['Pump 3 whine reported by night watch', 'Pump 3 bearing reseated at 0930, whine gone.'], ['Port nav lamp flickering', 'Port nav lamp swapped at 1040; steady since.'],
  ['Sensor pallet 2 drifting off true', 'Pallet 2 re-zeroed, drift now under 0.1 degree.'], ['Comms log missing hour 0300', 'Hour 0300 restored from the backup buffer.'],
  ['Helm chair squeaks on turns', 'Chair pivot greased at shift change, silent now.'], ['Ops display ghosting on panel 4', 'Panel 4 driver reset at 1115; no ghosting.'],
  ['Long-range array alignment due', 'Array alignment finished at 0820, logged.'], ['Relay 7 static on channel 2', 'Relay 7 filter replaced; channel 2 clean.']];
const NODS = ['Aye, sir.', 'Will do.', 'Noted, I\'ll look into it.', 'Understood.', 'On my list.', 'Yes, yeoman.'];

return define({
  job: { billet: 'yeoman', label: 'Walk the captain\'s deck round notes', type: 'task:quiet_watch' },
  title: 'Pin a real answer to each round note', dept: 'command', host: 'room', siteName: 'Station', verb: 'Ask',
  how: 'At each station the officer answers the captain\'s note in turns. Tap E only when they give the real answer: specific, and about this note. Nods and answers about something else do not count.',
  keys: ['E tap: write the answer down'], limit: 38, maxFaults: 3,
  fingerprint: { verb: 'pin the answer', input: 'e-tap', win: 'each station note answered with the officer\'s specific on-topic reply written beside it',
    fail: 'writing down a nod or an answer to a different note as if it closed the item',
    rule: 'The panel shows the note and the officer\'s current words, which change every second or so. Tap E while the words give a concrete fix for this note; never on a bare acknowledgement or another station\'s fix.' },
  rush: 'Read the notes out at a walk and took every nod as done.',
  captions: { nod: 'officer: "aye"', 'off topic': 'officer shrugs' },
  says: { nod: 'That was a nod, not an answer. The note stays open.', 'off topic': 'That answer was about a different note. Wait for this one.' },
  create(seed, opts) {
    const m = room(machine(this, seed, opts), [{ name: 'Helm', prop: 'helm' }, { name: 'Ops station', prop: 'opsstation' }, { name: 'Sensor station', prop: 'sensorstation' }, { name: 'Comms station', prop: 'commsstation' }]), r = m.rnd;
    const per = m.calm ? 1.9 : 1.35, notes = shuffle(r, NOTES);
    m.st = m.sites.map((_, i) => { const [note, real] = notes[i], other = notes[(i + 4) % notes.length][1], nods = shuffle(r, NODS).slice(0, 2);
      return { note, lines: shuffle(r, [{ s: real, ok: 1 }, { s: other, off: 1 }, { s: nods[0] }, { s: nods[1] }]), ph: rf(r, 0, per * 4) }; });
    const say = (u) => { const k = Math.floor(u.ph / per) % u.lines.length; return { line: u.lines[k], frac: (u.ph % per) / per }; };
    m.step = (dt, inp = {}) => {
      if (!m.live(dt, inp.away)) return; const s = m.cur(inp); if (!s) return; const i = m.next, u = m.st[i]; u.ph += dt;
      if (inp.press) { const { line } = say(u); if (line.ok) { m.finish(i); return; } m.fault(line.off ? 'off topic' : 'nod'); }
      s.prog = clamp(u.ph / (per * 4)) * 0.5;
    };
    m.hint = (f = 0) => { const i = m.next; if (i < 0) return { at: -1 }; const { line, frac } = say(m.st[i]); return { at: i, press: !!line.ok && frac > 0.3 && frac < 0.8 && f % 2 === 0, hold: false }; };
    m.bad = (f = 0) => { const i = m.next; if (i < 0) return { at: -1 }; const { line } = say(m.st[i]); return { at: i, press: !line.ok && f % 3 === 0 }; };
    m.view = () => ({ st: m.st.map(u => [u.note, u.lines.map(l => !!l.ok)]) });
    m.panel = (i) => { const u = m.st[i]; if (!u) return null; const { line, frac } = say(u); return { label: u.note, value: `"${line.s}"`, bar: 1 - frac }; };
    m.prompt = (i) => (m.st[i] ? 'Listen: tap [E] only on the specific answer to this note' : '');
    return m;
  },
});
})();
